// Truth-driven tests for batch126: keybindingResolver.ts.
// Truth generated by tool/ts2dart/_batch126_truth.cjs from real transpiled TS.
import 'dart:convert';
import 'dart:io';

import 'package:flutter_test/flutter_test.dart';
import 'package:semi_design_flutter/src/monaco/base/common/keybindings.dart'
    as kbbase;
import 'package:semi_design_flutter/src/monaco/platform/contextkey/common/contextkey.dart'
    as ck;
import 'package:semi_design_flutter/src/monaco/platform/keybinding/common/keybindingsRegistry.dart'
    as registry;
import 'package:semi_design_flutter/src/monaco/platform/keybinding/common/keybindingResolver.dart'
    as resolver;
import 'package:semi_design_flutter/src/monaco/platform/keybinding/common/resolvedKeybindingItem.dart'
    as resolved;

final Map<String, dynamic> _truth =
    jsonDecode(File('tool/ts2dart/batch126_truth.json').readAsStringSync())
        as Map<String, dynamic>;

Object? _norm(Object? v) {
  if (v == 'undefined') return null;
  if (v is List) return v.map(_norm).toList();
  if (v is Map) {
    return v.map<String, Object?>(
        (Object? key, Object? value) => MapEntry<String, Object?>('$key', _norm(value)));
  }
  return v;
}

void _expectDeep(Object? actual, Object? expected, String label) {
  expect(_norm(actual), _norm(expected), reason: label);
}

Map<String, dynamic> _section(String name) =>
    (_truth[name] as Map).cast<String, dynamic>();
List<dynamic> _listSection(String name) => _truth[name] as List<dynamic>;

class _FakeResolvedKeybinding implements kbbase.ResolvedKeybinding {
  _FakeResolvedKeybinding(this.dispatch);

  final List<String> dispatch;

  @override
  List<String?> getDispatchChords() => List<String?>.from(dispatch);
  @override
  List<String?> getSingleModifierDispatchChords() => <String?>[];
  @override
  noSuchMethod(Invocation invocation) => super.noSuchMethod(invocation);
}

class _Ctx implements ck.IContext {
  _Ctx(this.map);

  final Map<String, Object?> map;

  @override
  Object? getValue(String key) => map[key];
}

class _CtxService implements ck.IContextKeyServiceType {
  _CtxService(this.map);

  final Map<String, Object?> map;

  @override
  bool contextMatchesRules(ck.ContextKeyExpression? rules) =>
      rules == null || rules.evaluate(_Ctx(map));

  @override
  noSuchMethod(Invocation invocation) => super.noSuchMethod(invocation);
}

ck.ContextKeyExpression? _when(Object? value) => value == null || value == 'undefined'
    ? null
    : ck.ContextKeyExpr.deserialize(value as String);

resolved.ResolvedKeybindingItem _item(
  List<String> chords,
  String? command,
  Object? args,
  Object? when,
  bool isDefault, [
  String? extensionId,
  bool isBuiltinExtension = false,
  bool bubble = false,
]) {
  final String? id = bubble && command != null && !command.startsWith('^')
      ? '^$command'
      : command;
  return resolved.ResolvedKeybindingItem(
    _FakeResolvedKeybinding(chords),
    id,
    args,
    _when(when),
    isDefault,
    extensionId,
    isBuiltinExtension,
  );
}

Map<String, Object?> _kbView(resolved.ResolvedKeybindingItem k) =>
    <String, Object?>{
      'command': k.command,
      'args': k.commandArgs,
      'chords': k.chords,
      'when': k.when?.serialize() ?? 'undefined',
      'isDefault': k.isDefault,
      'extensionId': k.extensionId,
      'isBuiltinExtension': k.isBuiltinExtension,
      'bubble': k.bubble,
    };

Map<String, Object?> _resultView(resolver.ResolutionResult r) =>
    <String, Object?>{
      'kind': r.kind,
      'commandId': r.commandId,
      'commandArgs': r.commandArgs,
      'isBubble': r.isBubble,
    };

void main() {
  test('b126 result kinds and static implication truth', () {
    final e = _section('enums');
    expect(resolver.ResultKind.NoMatchingKb, e['NoMatchingKb']);
    expect(resolver.ResultKind.MoreChordsNeeded, e['MoreChordsNeeded']);
    expect(resolver.ResultKind.KbFound, e['KbFound']);
    _expectDeep(_resultView(resolver.NoMatchingKb), e['NoMatchingKbObject'],
        'NoMatchingKb object');

    for (final dynamic row in _listSection('whenIncluded')) {
      final Map<String, dynamic> r = row as Map<String, dynamic>;
      expect(
        resolver.KeybindingResolver.whenIsEntirelyIncluded(
            _when(r['a']), _when(r['b'])),
        r['value'],
        reason: 'whenIsEntirelyIncluded(${r['a']}, ${r['b']})',
      );
    }
  });

  test('b126 constructor maps and map insertion', () {
    final e = _section('construct');
    final logs = <String>[];
    final r = resolver.KeybindingResolver(
      <resolved.ResolvedKeybindingItem>[
        _item(<String>['A'], 'cmd.a', <String, Object?>{'n': 1}, null, true),
        _item(<String>['B'], 'cmd.neg', null, null, true),
        _item(<String>['C'], 'cmd.false', null, 'false', true),
        _item(<String>[], 'cmd.unbound', null, null, true),
      ],
      <resolved.ResolvedKeybindingItem>[
        _item(<String>['D'], 'cmd.user', <Object?>[1, 2], 'a', false, 'ext.u'),
      ],
      (String s) => logs.add(s),
    );
    _expectDeep(r.getDefaultKeybindings().map(_kbView).toList(), e['defaults'],
        'defaults');
    _expectDeep(r.getKeybindings().map(_kbView).toList(), e['keybindings'],
        'keybindings');
    _expectDeep(
      r.getDefaultBoundCommands().entries
          .map((MapEntry<String, bool> entry) => <Object?>[entry.key, entry.value])
          .toList(),
      e['boundCommands'],
      'boundCommands',
    );
    _expectDeep(
        r.lookupKeybindings('cmd.a').map(_kbView).toList(), e['lookupA'], 'lookupA');
    _expectDeep(r.lookupKeybindings('cmd.false').map(_kbView).toList(),
        e['lookupFalse'], 'lookupFalse');
    expect(logs, isEmpty);
  });

  test('b126 handleRemovals uses chord prefix and when implication', () {
    final rules = <resolved.ResolvedKeybindingItem>[
      _item(<String>['A'], 'rm.all', null, null, true),
      _item(<String>['B'], 'rm.bychord', null, null, true),
      _item(<String>['C'], 'rm.bywhen', null, 'a', true),
      _item(<String>['D'], 'rm.bywhen', null, 'a && b', true),
      _item(<String>['E'], 'keep.nondefault', null, null, false),
      _item(<String>['H'], 'keep.noRemoval', null, null, true),
      _item(<String>[], '-rm.all', null, null, true),
      _item(<String>['B'], '-rm.bychord', null, null, true),
      _item(<String>['C'], '-rm.bywhen', null, 'a', true),
      _item(<String>['D'], '-rm.bywhen', null, 'a && b && c', true),
      _item(<String>['E'], '-keep.nondefault', null, null, true),
    ];
    _expectDeep(
      resolver.KeybindingResolver.handleRemovals(rules).map(_kbView).toList(),
      _truth['removals'],
      'removals',
    );
  });

  test('b126 applyAliases inherits bindings and honors source removals', () {
    final e = _section('aliases');
    final defaults = <resolved.ResolvedKeybindingItem>[
      _item(<String>['S'], 'src', 1, null, true, 'ext.s', true),
      _item(<String>['T'], 'unrelated', null, null, true),
    ];
    final overrides = <resolved.ResolvedKeybindingItem>[
      _item(<String>['U'], 'src', 2, 'b', false),
    ];
    final aliases = <registry.IKeybindingAlias>[
      registry.IKeybindingAlias(
          command: 'alias', source: 'src', when: _when('a')),
      registry.IKeybindingAlias(
          command: 'alias2', source: 'src', when: null),
    ];
    final applied = resolver.KeybindingResolver.applyAliases(
        defaults, overrides, aliases);
    _expectDeep(applied.defaults.map(_kbView).toList(), e['defaults'],
        'alias defaults');
    _expectDeep(applied.overrides.map(_kbView).toList(), e['overrides'],
        'alias overrides');

    final withRemoval = resolver.KeybindingResolver.applyAliases(
      <resolved.ResolvedKeybindingItem>[
        _item(<String>['S'], '-src', null, null, true),
        _item(<String>['S2'], 'src', 3, null, true),
      ],
      <resolved.ResolvedKeybindingItem>[
        _item(<String>['V'], 'src', 4, null, false),
      ],
      aliases,
    );
    _expectDeep(withRemoval.defaults.map(_kbView).toList(),
        e['withRemovalDefaults'], 'alias removal defaults');
    _expectDeep(withRemoval.overrides.map(_kbView).toList(),
        e['withRemovalOverrides'], 'alias removal overrides');

    final same = resolver.KeybindingResolver.applyAliases(
        defaults, overrides, <registry.IKeybindingAlias>[]);
    expect(identical(same.defaults, defaults), e['empty']);
    expect(identical(same.overrides, overrides), e['empty']);
  });

  test('b126 resolve chords, when clauses, args, bubble and logs', () {
    final r = resolver.KeybindingResolver(
      <resolved.ResolvedKeybindingItem>[
        _item(<String>['A'], 'one', <String, Object?>{'n': 1}, null, true),
        _item(<String>['A', 'B'], 'two', <Object?>[1, 2], 'cond', false,
            'ext.x', true, true),
        _item(<String>['A', 'C'], 'three', 'three-args', '!cond', true),
        _item(<String>['Z'], 'zed', null, null, true),
      ],
      <resolved.ResolvedKeybindingItem>[],
      (String s) {},
    );

    for (final dynamic row in _listSection('resolve')) {
      final Map<String, dynamic> c = row as Map<String, dynamic>;
      final logs = <String>[];
      final local = resolver.KeybindingResolver(
        <resolved.ResolvedKeybindingItem>[
          _item(<String>['A'], 'one', <String, Object?>{'n': 1}, null, true),
          _item(<String>['A', 'B'], 'two', <Object?>[1, 2], 'cond', false,
              'ext.x', true, true),
          _item(<String>['A', 'C'], 'three', 'three-args', '!cond', true),
          _item(<String>['Z'], 'zed', null, null, true),
        ],
        <resolved.ResolvedKeybindingItem>[],
        (String s) => logs.add(s),
      );
      final state = (c['state'] as Map).cast<String, Object?>();
      final chords = (c['chords'] as List).cast<String>();
      _expectDeep(
        _resultView(
            local.resolve(_Ctx(state), chords, c['keypress'] as String)),
        c['value'],
        'resolve ${c['name']}',
      );
      _expectDeep(logs, c['logs'], 'resolve ${c['name']} logs');
    }
    expect(r, isNotNull);
  });

  test('b126 lookup order, context selection and enforceContextCheck', () {
    final e = _section('lookup');
    final r = resolver.KeybindingResolver(
      <resolved.ResolvedKeybindingItem>[
        _item(<String>['A'], 'lookup', 'first', null, true),
        _item(<String>['B'], 'lookup', 'second', 'a', true),
        _item(<String>['C'], 'lookup', 'third', 'a && b', false),
      ],
      <resolved.ResolvedKeybindingItem>[],
      (String s) {},
    );
    _expectDeep(r.lookupKeybindings('lookup').map(_kbView).toList(), e['all'],
        'lookup all');
    _expectDeep(r.lookupKeybindings('nope').map(_kbView).toList(), e['missing'],
        'lookup missing');
    _expectDeep(
      r.lookupPrimaryKeybinding('single', _CtxService(<String, Object?>{})) ==
              null
          ? null
          : _kbView(r.lookupPrimaryKeybinding(
              'single', _CtxService(<String, Object?>{}))!),
      e['primarySingle'],
      'primarySingle',
    );

    resolved.ResolvedKeybindingItem? viewFor(Object? expected,
        {required Map<String, Object?> state, required bool enforce}) {
      final v = r.lookupPrimaryKeybinding(
          'lookup', _CtxService(state), enforce);
      return v;
    }

    _expectDeep(
      viewFor(e['primaryDefault'],
              state: <String, Object?>{'a': false}, enforce: false) == null
          ? null
          : _kbView(viewFor(e['primaryDefault'],
              state: <String, Object?>{'a': false}, enforce: false)!),
      e['primaryDefault'],
      'primaryDefault',
    );
    _expectDeep(
      viewFor(e['primaryStrict'],
              state: <String, Object?>{'a': false}, enforce: true) == null
          ? null
          : _kbView(viewFor(e['primaryStrict'],
              state: <String, Object?>{'a': false}, enforce: true)!),
      e['primaryStrict'],
      'primaryStrict',
    );
    _expectDeep(
      viewFor(e['primaryMatch'],
              state: <String, Object?>{'a': true}, enforce: true) == null
          ? null
          : _kbView(viewFor(e['primaryMatch'],
              state: <String, Object?>{'a': true}, enforce: true)!),
      e['primaryMatch'],
      'primaryMatch',
    );
  });

  test('b126 shorter chord shadows longer binding in lookup map', () {
    final e = _section('shadow');
    final r = resolver.KeybindingResolver(
      <resolved.ResolvedKeybindingItem>[
        _item(<String>['A'], 'short', null, null, true),
        _item(<String>['A', 'B'], 'long', null, null, true),
      ],
      <resolved.ResolvedKeybindingItem>[],
      (String s) {},
    );
    _expectDeep(r.lookupKeybindings('short').map(_kbView).toList(), e['short'],
        'shadow short');
    _expectDeep(r.lookupKeybindings('long').map(_kbView).toList(), e['long'],
        'shadow long');
    _expectDeep(
      _resultView(r.resolve(_Ctx(<String, Object?>{}), <String>['A'], 'B')),
      e['resolved'],
      'shadow resolved',
    );
  });
}
